import json
from hypothesis import strategies as st

MOD = 10**9 + 7

@st.composite
def gen(draw):
    n = draw(st.one_of(st.just(1), st.just(2), st.integers(1, 4)))
    target = draw(st.one_of(st.just(1), st.just(2), st.integers(1, 7)))
    return f"{n}\n{target}"

def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    try:
        n = json.loads(lines[0])
        target = json.loads(lines[1])
    except Exception:
        return False
    if not (isinstance(n, int) and isinstance(target, int)):
        return False
    return 1 <= n <= 10**9 and 1 <= target <= 10**9

def ref(inp):
    lines = inp.strip().split("\n")
    n = json.loads(lines[0])
    target = json.loads(lines[1])
    # Exhaustive search: choose n distinct positive integers from a bounded
    # range such that no two distinct chosen values sum to target; minimize sum.
    bound = 2 * n + target
    best = None
    for combo in itertools.combinations(range(1, bound + 1), n):
        s = set(combo)
        ok = True
        for x in combo:
            if (target - x) in s and (target - x) != x:
                ok = False
                break
            if target - x == x:
                # x paired with itself is not allowed (distinct indices required)
                continue
        if not ok:
            continue
        total = sum(combo)
        if best is None or total < best:
            best = total
    return json.dumps(best % MOD)
